package sshkey

import (
	"crypto/rand"
	"fmt"
	"os"

	"golang.org/x/crypto/ssh"
)

// SignChallenge signs the proof prefix, a NUL separator, and the raw nonce.
// It returns an RFC 4253 signature blob, JSON-encoded by the caller as Base64.
// Private key bytes stay local.
func SignChallenge(privatePath string, nonce []byte) ([]byte, error) {
	if len(nonce) == 0 {
		return nil, fmt.Errorf("empty SSH key challenge")
	}
	// #nosec G304 -- the caller supplies the fresh local key generated by the CLI; the challenge cannot select a file.
	key, err := os.ReadFile(privatePath)
	if err != nil {
		return nil, err
	}
	signer, err := ssh.ParsePrivateKey(key)
	if err != nil {
		return nil, fmt.Errorf("parse signing key: %w", err)
	}
	message := append([]byte("containarium-ssh-key-proof-v1\x00"), nonce...)
	var sig *ssh.Signature
	if rsaSigner, ok := signer.(ssh.AlgorithmSigner); ok && signer.PublicKey().Type() == ssh.KeyAlgoRSA {
		sig, err = rsaSigner.SignWithAlgorithm(rand.Reader, message, ssh.KeyAlgoRSASHA512)
	} else {
		sig, err = signer.Sign(rand.Reader, message)
	}
	if err != nil {
		return nil, fmt.Errorf("sign challenge: %w", err)
	}
	return ssh.Marshal(sig), nil
}
